import spidev
import sys

# Constants
MAX_CHANNEL = 7
MAX_COUNT = 4095
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MODE = 0
SPI_SPEED = 1000000  # 1 MHz

def initialize_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED
        spi.mode = SPI_MODE
        return spi
    except Exception as e:
        print(f"SPI initialization failed: {e}")
        return None

def read_raw_channel(channel, spi):
    if not (0 <= channel <= MAX_CHANNEL):
        return -1

    try:
        # MCP3208 command format: 0b11000CCC DDDDDDDD
        # C: channel bits, D: don't care bits
        command = 0b11000000 | (channel << 3)
        response = spi.xfer2([command, 0])

        # Combine the two bytes to form the 12-bit result
        result = ((response[1] & 0x03) << 8) | response[2]
        return result
    except Exception as e:
        print(f"SPI transfer failed: {e}")
        return -1
    finally:
        if spi:
            spi.close()

def read_normalized_channel(channel, spi):
    raw_value = read_raw_channel(channel, spi)
    if raw_value == -1:
        return -1
    return raw_value / MAX_COUNT

def read_channel(channel, return_type='raw'):
    spi = initialize_spi()
    if not spi:
        return -1

    if return_type == 'raw':
        result = read_raw_channel(channel, spi)
    elif return_type == 'normalized':
        result = read_normalized_channel(channel, spi)
    else:
        result = -1

    return result

if __name__ == "__main__":
    channel = 0
    raw_value = read_channel(channel, 'raw')
    normalized_value = read_channel(channel, 'normalized')

    if raw_value != -1:
        print(f"Raw value for channel {channel}: {raw_value}")
    else:
        print(f"Failed to read raw value for channel {channel}")

    if normalized_value != -1:
        print(f"Normalized value for channel {channel}: {normalized_value:.4f}")
    else:
        print(f"Failed to read normalized value for channel {channel}")

