        self._write_register(ADS1015_REG_POINTER_LOWTHRESH, [(threshold_low >> 8) & 0xFF, threshold_low & 0xFF])

        for _ in range(num_readings):
            result = self.read_adc_single_ended(channel, pga, sps)
            if result is not None:
                logger.info(f"Comparator reading: {result}")

    def close(self):
        if self.bus:
            self._close_bus()

