import csv
import statistics
from datetime import datetime
from gpiozero import MCP3008
from contextlib import contextmanager

class SoilMoistureSensor:
    def __init__(self, dry=820, wet=400, history_size=25):
        self.dry = dry
        self.wet = wet
        self.history_size = history_size
        self.history = []
        self.adc = MCP3008(channel=2)
        self.running = True

    def read_moisture(self):
        try:
            raw_value = self.adc.value * 1023
            if raw_value == 0 or raw_value == 1023:
                raise ValueError("Sensor absent or disconnected")
            moisture_percentage = 100 * (self.dry - raw_value) / (self.dry - self.wet)
            return max(0, min(100, moisture_percentage))
        except Exception as e:
            print(f"Error reading moisture: {e}")
            return None

    def update_history(self, value):
        self.history.append(value)
        if len(self.history) > self.history_size:
            self.history.pop(0)

    def compute_statistics(self):
        if not self.history:
            return None, None
        mean = statistics.mean(self.history)
        stdev = statistics.stdev(self.history) if len(self.history) > 1 else 0
        return mean, stdev

    def log_reading(self, timestamp, moisture_percentage):
        with open('soil_moisture_log.csv', 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, moisture_percentage])

    def run(self):
        for _ in range(25):
            if not self.running:
                break
            moisture_percentage = self.read_moisture()
            if moisture_percentage is not None:
                self.update_history(moisture_percentage)
                timestamp = datetime.now().isoformat()
                self.log_reading(timestamp, moisture_percentage)
                mean, stdev = self.compute_statistics()
                print(f"Timestamp: {timestamp}, Moisture: {moisture_percentage:.2f}%, Mean: {mean:.2f}%, Std Dev: {stdev:.2f}%")
            time.sleep(1)

    def stop(self):
        self.running = False

@contextmanager
def graceful_exit(sensor):
    def handler(signum, frame):
        sensor.stop()

    signal.signal(signal.SIGINT, handler)
    signal.signal(signal.SIGTERM, handler)

    try:
        yield
    finally:
        sensor.stop()
        print("Resources released and program terminated gracefully.")

if __name__ == "__main__":
    sensor = SoilMoistureSensor()
    with graceful_exit(sensor):
        sensor.run()

