import time
import logging
import spidev
import RPi.GPIO as GPIO
from gpiozero import OutputDevice
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    def __init__(self, adc_channel=0, pump_pin=18, dry_threshold=450):
        self.adc_channel = adc_channel
        self.pump_pin = pump_pin
        self.dry_threshold = dry_threshold
        self.spi = None
        self.pump = None
        self._setup()

    def _setup(self):
        try:
            # Setup SPI
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 1350000
            self.spi.mode = 0b00

            # Setup GPIO
            GPIO.setmode(GPIO.BCM)
            self.pump = OutputDevice(self.pump_pin, active_high=True)
        except Exception as e:
            logging.error(f"Setup failed: {e}")
            self.close()
            raise

    def read_moisture(self):
        try:
            # MCP3008 command format: Start bit, single-ended bit, D2, D1, D0
            command = [1, (8 + self.adc_channel) << 4, 0]
            response = self.spi.xfer2(command)
            adc_value = ((response[1] & 3) << 8) + response[2]
            return adc_value
        except Exception as e:
            logging.error(f"SPI transaction failed: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self.pump.on()
            time.sleep(seconds)
            self.pump.off()
        except Exception as e:
            logging.error(f"Failed to run pump: {e}")

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is None:
            return False

        if moisture > self.dry_threshold:
            self.run_pump(2)
            return True
        return False

    def close(self):
        if self.spi:
            self.spi.close()
        if self.pump:
            self.pump.close()
        GPIO.cleanup()

@contextmanager
def smart_garden_controller_context():
    controller = SmartGardenController()
    try:
        yield controller
    finally:
        controller.close()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        if controller.irrigation_cycle():
            logging.info("Irrigation cycle completed.")
        else:
            logging.info("Soil is wet enough; no irrigation needed.")
        time.sleep(interval_seconds)

if __name__ == "__main__":
    try:
        with smart_garden_controller_context() as controller:
            schedule_cycles(controller, cycle_count=10, interval_seconds=3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

