import argparse
import logging
import queue
import threading
import time
from gpiozero import DigitalInputDevice
from gpiozero.pins.bcm import BCMGPIO
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn
import adafruit_mcp3xxx as MCP
import board
import busio
import signal
import sys

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue
        self.running = False
        self.stop_event = threading.Event()

        if self.sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError("GPIO pins must be provided for digital sensors.")
            self.device = DigitalInputDevice(gpio_pins, pin_factory=BCMGPIO)
        elif self.sensor_type == 'analog':
            if not channels:
                raise ValueError("Channels must be provided for analog sensors.")
            try:
                spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO, baudrate=spi_speed)
                self.mcp = MCP3008(spi, device=0)
                self.channel = AnalogIn(self.mcp, channels)
            except Exception as e:
                logging.error(f"SPI initialization failed for sensor {sensor_id}: {e}")
                raise
        else:
            raise ValueError("Invalid sensor type. Must be 'digital' or 'analog'.")

    def run(self):
        self.running = True
        while not self.stop_event.is_set():
            try:
                if self.sensor_type == 'digital':
                    if self.device.value == 1:
                        self.log_event()
                        time.sleep(0.1)  # Debounce
                elif self.sensor_type == 'analog':
                    if self.channel.value >= self.threshold:
                        self.log_event()
                        time.sleep(0.1)  # Debounce
                time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error reading sensor {self.sensor_id}: {e}")

    def stop(self):
        self.stop_event.set()
        if self.sensor_type == 'digital':
            self.device.close()
        elif self.sensor_type == 'analog':
            del self.channel
            del self.mcp

    def log_event(self):
        if self.log_queue:
            try:
                self.log_queue.put(f"Event detected on sensor {self.sensor_id}")
            except Exception as e:
                logging.error(f"Failed to log event for sensor {self.sensor_id}: {e}")

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    for sensor in sensors:
        sensor.stop()
    sys.exit(0)

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor")
    parser.add_argument("--sensor_type", required=True, choices=['digital', 'analog'], help="Type of sensor (digital or analog)")
    parser.add_argument("--threshold", type=float, required=True, help="Threshold for detecting sound")
    parser.add_argument("--sample_rate", type=float, required=True, help="Sample rate in Hz")
    parser.add_argument("--log_file", required=True, help="Log file path")
    parser.add_argument("--gpio_pins", type=int, nargs='+', help="GPIO pins for digital sensors")
    parser.add_argument("--channels", type=int, nargs='+', help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed")
    parser.add_argument("--sensor_ids", type=int, nargs='+', required=True, help="Sensor IDs")

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []

    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(
            sensor_id=sensor_id,
            sensor_type=args.sensor_type,
            threshold=args.threshold,
            sample_rate=args.sample_rate,
            gpio_pins=args.gpio_pins,
            channels=args.channels,
            spi_speed=args.spi_speed,
            log_queue=log_queue
        )
        sensors.append(sensor)
        threading.Thread(target=sensor.run).start()

    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            while not log_queue.empty():
                message = log_queue.get()
                logging.info(message)
            time.sleep(0.1)
    except KeyboardInterrupt:
        signal_handler(None, None)

if __name__ == "__main__":
    main()

