import os
import signal
import sys
import time
import logging
import threading
import multiprocessing
import traceback
from datetime import datetime
from multiprocessing import Process, Event
from signal import SIGUSR1, SIGKILL, SIGTERM, SIGINT, SIGHUP, SIGABRT
import atexit

# Configuration
CONFIG_FILE = '/etc/systemd/system/console.service'
CONFIG_KEY = 'Environment=CONSOLE_PID='
LOG_DIR = '/home/pi/Console/.HistoryBuffer'
TOMBSTONE_FILE = '/home/pi/.tombstoneW'
PROCESS_TITLE = "Console Watchdog"
FAILSAFE_PING_INTERVAL = 30
KEEP_ALIVE_TIMEOUT = 60
EXIT_CODE_SIGINT = 94
EXIT_CODE_SIGABRT = 93

# Setup logging
if not os.path.exists(LOG_DIR):
    os.makedirs(LOG_DIR)
log_file = os.path.join(LOG_DIR, 'hlogW')

def log_message(message):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    with open(log_file, 'a') as f:
        f.write(f"{timestamp} - {message}\n")
        f.flush()

def read_console_pid():
    with open(CONFIG_FILE, 'r') as f:
        for line in f:
            if line.startswith(CONFIG_KEY):
                return int(line.split('=')[1].strip())
    return None

def set_process_title(title):
    try:
        import setproctitle
        setproctitle.setproctitle(title)
    except ImportError:
        log_message("setproctitle module not found, process title not set.")

def handle_sigterm(signum, frame):
    log_message("Received SIGTERM from systemd.")
    time.sleep(30)
    sys.exit(0)

def handle_sigint(signum, frame):
    log_message("Received SIGINT.")
    sys.exit(EXIT_CODE_SIGINT)

def handle_sigusr1(signum, frame):
    log_message("Received SIGUSR1.")
    sys.exit(EXIT_CODE_SIGINT)

def handle_sighup(signum, frame):
    log_message("Received SIGHUP, ignoring.")

def handle_sigabrt(signum, frame):
    with open(TOMBSTONE_FILE, 'w') as f:
        traceback.print_stack(file=f)
    sys.exit(EXIT_CODE_SIGABRT)

def fail_safe_ping(injector_event, keep_alive_event):
    while True:
        try:
            log_message("FailSafePing event posted.")
            time.sleep(FAILSAFE_PING_INTERVAL)
            if not injector_event.is_set():
                injector_event.set()
                keep_alive_event.wait(KEEP_ALIVE_TIMEOUT)
                injector_event.clear()
        except Exception as e:
            log_message(f"Exception in fail_safe_ping: {e}")

def check_main_thread_alive():
    while True:
        try:
            if not threading.main_thread().is_alive():
                log_message("Main thread not alive, sending SIGINT to watchdog.")
                os.kill(os.getpid(), SIGINT)
            time.sleep(FAILSAFE_PING_INTERVAL)
        except Exception as e:
            log_message(f"Exception in check_main_thread_alive: {e}")

def watchdog_process(console_pid, injector_event, keep_alive_event):
    try:
        while True:
            try:
                if not injector_event.is_set():
                    log_message("KeepAlive timeout expired.")
                    if os.kill(console_pid, 0) == 0:
                        os.kill(console_pid, SIGUSR1)
                        time.sleep(3)
                        os.kill(console_pid, SIGKILL)
                    else:
                        log_message(f"Console process {console_pid} does not exist.")
            except Exception as e:
                log_message(f"Exception in watchdog_process: {e}")
            time.sleep(1)
    except Exception as e:
        log_message(f"Unexpected exception in watchdog_process: {e}")

def atexit_handler(console_pid):
    try:
        if os.kill(console_pid, 0) == 0:
            os.kill(console_pid, SIGUSR1)
            time.sleep(3)
            os.kill(console_pid, SIGKILL)
    except Exception as e:
        log_message(f"Exception in atexit_handler: {e}")

if __name__ == "__main__":
    console_pid = read_console_pid()
    if console_pid is None:
        log_message("Console PID not found in configuration.")
        sys.exit(1)

    set_process_title(PROCESS_TITLE)

    signal.signal(SIGTERM, handle_sigterm)
    signal.signal(SIGINT, handle_sigint)
    signal.signal(SIGUSR1, handle_sigusr1)
    signal.signal(SIGHUP, handle_sighup)
    signal.signal(SIGABRT, handle_sigabrt)

    injector_event = Event()
    keep_alive_event = Event()

    injector_thread = threading.Thread(target=fail_safe_ping, args=(injector_event, keep_alive_event))
    injector_thread.start()

    main_thread_checker = threading.Thread(target=check_main_thread_alive)
    main_thread_checker.start()

    watchdog = Process(target=watchdog_process, args=(console_pid, injector_event, keep_alive_event))
    watchdog.start()

    atexit.register(atexit_handler, console_pid)

    try:
        injector_thread.join()
        main_thread_checker.join()
        watchdog.join()
    except KeyboardInterrupt:
        log_message("KeyboardInterrupt received, exiting.")
    except Exception as e:
        log_message(f"Unexpected exception: {e}")
    finally:
        log_message("Watchdog exiting.")

