import serial
import fractions
from typing import Tuple

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("degrees_decimal must be a real number.")

    sign = -1 if degrees_decimal < 0 else 1
    degrees_decimal = abs(degrees_decimal)

    degrees = int(degrees_decimal)
    minutes = int((degrees_decimal - degrees) * 60)
    seconds = (degrees_decimal - degrees - minutes / 60) * 3600

    return (sign * degrees, sign * minutes, sign * seconds)

def number_to_exif_rational(number: float) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("number must be a real number.")

    try:
        fraction = fractions.Fraction(number).limit_denominator(1000)
    except (TypeError, ValueError):
        raise ValueError("number cannot be converted to a fraction.")

    numerator, denominator = fraction.numerator, fraction.denominator

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("Numerator and denominator must be integers.")

    return (numerator, denominator)

def read_gps_data():
    try:
        with serial.Serial('/dev/serial0', baudrate=9600, timeout=1) as ser:
            while True:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line.startswith('$GPGGA'):
                    print(line)
    except serial.SerialException as e:
        print(f"Serial error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    try:
        # Example usage of the utility functions
        print(degrees_decimal_to_dms(37.7749))  # Example for latitude
        print(number_to_exif_rational(37.7749))  # Example for rational conversion

        # Start reading GPS data
        read_gps_data()
    except (ValueError, TypeError) as e:
        print(f"Error: {e}")

