import sys
import argparse
import csv
import os
import time
from datetime import datetime
from gpiozero import DigitalInputDevice
from gpiozero.pins.bcm import BCMGPIO
from picamera import PiCamera
from picamera.exc import PiCameraError
import logging

def setup_logging(log_file):
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    if log_file:
        try:
            file_handler = logging.FileHandler(log_file)
            file_handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
            logging.getLogger().addHandler(file_handler)
        except Exception as e:
            logging.error(f"Failed to set up file logging: {e}")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Monitor vibration sensors and capture images.")
    parser.add_argument('-g', '--gpio', type=int, nargs=3, required=True, help="List of GPIO pins for sensors.")
    parser.add_argument('-l', '--log_file', type=str, help="CSV log file path.")
    parser.add_argument('-i', '--interval', type=float, default=1.0, help="Sensor sampling interval in seconds.")
    parser.add_argument('-c', '--calibrate', type=int, default=10, help="Calibration duration in seconds.")
    parser.add_argument('-p', '--picture_interval', type=int, default=60, help="Picture interval in seconds.")
    return parser.parse_args()

def initialize_sensors(pins):
    sensors = []
    for pin in pins:
        try:
            sensor = DigitalInputDevice(pin, pull='down', pin_factory=BCMGPIO())
            sensors.append(sensor)
        except Exception as e:
            logging.error(f"Failed to initialize sensor on pin {pin}: {e}")
            sys.exit(1)
    return sensors

def calibrate_sensors(sensors, duration):
    logging.info("Starting calibration...")
    start_time = time.time()
    high_counts = [0] * len(sensors)
    total_samples = 0

    while time.time() - start_time < duration:
        for i, sensor in enumerate(sensors):
            if sensor.value:
                high_counts[i] += 1
        total_samples += 1
        time.sleep(0.1)

    if total_samples == 0:
        logging.error("Calibration failed: No samples collected.")
        sys.exit(1)

    baselines = [(count / total_samples) * 100 for count in high_counts]
    thresholds = [baseline + 20 for baseline in baselines]
    logging.info(f"Calibration complete. Baselines: {baselines}, Thresholds: {thresholds}")
    return thresholds

def log_data(log_file, timestamp, states):
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp] + states)
            csvfile.flush()
    except Exception as e:
        logging.error(f"Failed to write to log file: {e}")
        print(f"{timestamp},{','.join(map(str, states))}")

def capture_image(camera, timestamp):
    try:
        image_path = os.path.join("images", f"{timestamp}.jpg")
        os.makedirs(os.path.dirname(image_path), exist_ok=True)
        camera.capture(image_path)
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")

def main():
    args = parse_arguments()
    setup_logging(args.log_file)

    sensors = initialize_sensors(args.gpio)
    thresholds = calibrate_sensors(sensors, args.calibrate)

    camera = None
    try:
        camera = PiCamera()
        camera.resolution = (1024, 768)
    except PiCameraError as e:
        logging.warning(f"Camera initialization failed: {e}")

    last_picture_time = time.time()

    try:
        while True:
            timestamp = datetime.now().strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3]
            high_counts = [0] * len(sensors)
            total_samples = 0

            start_time = time.time()
            while time.time() - start_time < args.interval:
                for i, sensor in enumerate(sensors):
                    if sensor.value:
                        high_counts[i] += 1
                total_samples += 1
                time.sleep(0.1)

            if total_samples == 0:
                states = [0] * len(sensors)
            else:
                states = [1 if (count / total_samples) * 100 > thresholds[i] else 0 for i, count in enumerate(high_counts)]

            log_data(args.log_file, timestamp, states)

            if camera and time.time() - last_picture_time >= args.picture_interval:
                capture_image(camera, timestamp)
                last_picture_time = time.time()

            time.sleep(max(0, args.interval - (time.time() - start_time)))

    except KeyboardInterrupt:
        logging.info("Shutting down...")
    finally:
        for sensor in sensors:
            sensor.close()
        if camera:
            camera.close()

if __name__ == "__main__":
    main()

