import os
import signal
import sys
import time
from contextlib import contextmanager
from gpiozero import PWMOutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory

# Constants
PWM_PIN = 17
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
DEFAULT_PWM = 1.0
TEMP_POLL_INTERVAL = 5

# Thresholds and PWM values
TEMP_THRESHOLDS = [65, 55, 50, 45]
PWM_VALUES = [1.0, 0.8, 0.6, 0.4, 0.4]

# Validate thresholds and PWM values
if len(TEMP_THRESHOLDS) + 1 != len(PWM_VALUES):
    raise ValueError("Thresholds and PWM values arrays must be of equal length.")
if not all(0.0 <= pwm <= 1.0 for pwm in PWM_VALUES):
    raise ValueError("Each PWM value must be in the range 0.0 to 1.0.")

# Context manager for PWM device
@contextmanager
def pwm_device(pin):
    pwm = PWMOutputDevice(pin, frequency=25, pin_factory=PiGPIOFactory())
    try:
        yield pwm
    finally:
        try:
            pwm.close()
        except Exception as e:
            print(f"Error closing PWM device: {e}", file=sys.stderr)

def read_cpu_temperature():
    try:
        with open(TEMP_FILE, 'r') as f:
            temp_str = f.read().strip()
            return float(temp_str) / 1000.0
    except Exception as e:
        print(f"Error reading temperature: {e}", file=sys.stderr)
        return None

def map_temperature_to_pwm(temp):
    for i, threshold in enumerate(TEMP_THRESHOLDS):
        if temp > threshold:
            return PWM_VALUES[i]
    return PWM_VALUES[-1]

def signal_handler(signum, frame, pwm):
    print("Shutting down...")
    try:
        pwm.value = DEFAULT_PWM
    except Exception as e:
        print(f"Error setting default PWM on shutdown: {e}", file=sys.stderr)
    sys.exit(0)

def main():
    # Setup signal handlers
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, pwm))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, pwm))

    try:
        with pwm_device(PWM_PIN) as pwm:
            print("Starting up...")
            pwm.value = DEFAULT_PWM
            print(f"Initial temperature: {read_cpu_temperature()} °C, Target PWM: {DEFAULT_PWM}")

            while True:
                temp = read_cpu_temperature()
                if temp is not None:
                    target_pwm = map_temperature_to_pwm(temp)
                    print(f"Current temperature: {temp} °C, Target PWM: {target_pwm}")
                    try:
                        pwm.value = target_pwm
                    except Exception as e:
                        print(f"Error setting PWM: {e}", file=sys.stderr)
                else:
                    print("Using default PWM due to temperature read error.")
                    pwm.value = DEFAULT_PWM

                time.sleep(TEMP_POLL_INTERVAL)

    except Exception as e:
        print(f"Error initializing PWM output: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

