import os
import signal
import logging
import time
from PIL import Image, ImageSequence, UnidentifiedImageError
from gpiozero import Display
from contextlib import contextmanager

logging.basicConfig(level=logging.INFO)

class AnimatedGif:
    def __init__(self, display, folder_path, width=None, height=None):
        self.display = display
        self.folder_path = folder_path
        self.width = width or display.width
        self.height = height or display.height
        self.gif_files = []
        self.frames = []
        self.loop_count = 0
        self._is_running = False

        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def load_files(self):
        if not os.path.exists(self.folder_path):
            raise FileNotFoundError(f"Folder {self.folder_path} does not exist")

        for filename in os.listdir(self.folder_path):
            if filename.endswith('.gif'):
                file_path = os.path.join(self.folder_path, filename)
                try:
                    with Image.open(file_path) as img:
