import time
import signal
import sys
from gpiozero import DigitalOutputDevice, DigitalInputDevice
from gpiozero.pins.bcm import BCMGPIO

# Constants
TRIG_PIN = 17
ECHO_PIN = 18
MAX_DISTANCE_CM = 400
MIN_DISTANCE_CM = 2
TANK_HEIGHT_CM = 50
MEASUREMENT_INTERVAL = 2  # seconds

# Setup GPIO
trig = DigitalOutputDevice(TRIG_PIN, pin_factory=BCMGPIO(), initial_value=False)
echo = DigitalInputDevice(ECHO_PIN, pin_factory=BCMGPIO())

def signal_handler(sig, frame):
    print("Signal received, shutting down...")
    cleanup()
    sys.exit(0)

def cleanup():
    trig.close()
    echo.close()
    print("GPIO resources released.")

def measure_distance():
    try:
        # Stabilize the sensor
        trig.value = False
        time.sleep(0.2)

        # Send 10us pulse
        trig.value = True
        time.sleep(0.00001)
        trig.value = False

        # Wait for echo to go high
        start_time = time.time()
        while not echo.is_active:
            if (time.time() - start_time) > 0.03:
                raise RuntimeError("Echo did not go high within 30ms")

        # Wait for echo to go low
        start_time = time.time()
        while echo.is_active:
            if (time.time() - start_time) > 0.03:
                raise RuntimeError("Echo did not go low within 30ms")

        # Calculate distance
        pulse_duration = time.time() - start_time
        distance_cm = pulse_duration * 17150  # Speed of sound in cm/s

        # Validate distance
        if not (MIN_DISTANCE_CM <= distance_cm <= MAX_DISTANCE_CM):
            raise ValueError(f"Invalid distance: {distance_cm} cm")

        return distance_cm

    except Exception as e:
        print(f"Error measuring distance: {e}")
        return None

def compute_water_level(distance_cm):
    if distance_cm is None:
        return None
    water_level_cm = TANK_HEIGHT_CM - distance_cm
    return max(0, min(water_level_cm, TANK_HEIGHT_CM))

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            try:
                distance_cm = measure_distance()
                if distance_cm is not None:
                    water_level_cm = compute_water_level(distance_cm)
                    print(f"Distance: {distance_cm:.2f} cm, Water Level: {water_level_cm:.2f} cm")
            except Exception as e:
                print(f"Error in loop iteration: {e}")

            time.sleep(MEASUREMENT_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}")

    finally:
        cleanup()

if __name__ == "__main__":
    main()

