import time
import RPi.GPIO as GPIO
from statistics import median

# Constants
TRIG_PIN = 5
ECHO_PIN = 6
SAMPLE_DELAY = 0.3  # 300 ms
ECHO_TIMEOUT = 1.0  # 1 second
DISTANCE_THRESHOLD = 5.0  # 5 cm

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIG_PIN, GPIO.OUT)
    GPIO.setup(ECHO_PIN, GPIO.IN)

def cleanup_gpio():
    GPIO.cleanup()

def send_trigger_pulse():
    GPIO.output(TRIG_PIN, True)
    time.sleep(0.00001)  # 10 microseconds
    GPIO.output(TRIG_PIN, False)

def get_distance():
    send_trigger_pulse()
    start_time = time.time()
    stop_time = start_time

    while GPIO.input(ECHO_PIN) == 0:
        start_time = time.time()
        if (start_time - stop_time) > ECHO_TIMEOUT:
            return None

    while GPIO.input(ECHO_PIN) == 1:
        stop_time = time.time()
        if (stop_time - start_time) > ECHO_TIMEOUT:
            return None

    time_elapsed = stop_time - start_time
    distance = (time_elapsed * 34300) / 2  # Speed of sound at 34300 cm/s
    return distance

def get_samples():
    samples = []
    for _ in range(10):
        distance = get_distance()
        if distance is not None:
            samples.append(distance)
        time.sleep(SAMPLE_DELAY)
    return samples

def detect_gesture(previous_distance, current_distance):
    if current_distance is None:
        return "error"
    if previous_distance is None:
        return "hold"
    distance_change = current_distance - previous_distance
    if distance_change < -DISTANCE_THRESHOLD:
        return "swipe_in"
    elif distance_change > DISTANCE_THRESHOLD:
        return "swipe_out"
    else:
        return "hold"

def main():
    setup_gpio()
    previous_distance = None

    try:
        while True:
            samples = get_samples()
            if not samples:
                print("Error: No valid distance samples.")
                continue

            current_distance = median(samples)
            gesture = detect_gesture(previous_distance, current_distance)

            if gesture == "error":
                print("Error: Sensor timeout or invalid reading.")
            else:
                print(gesture)

            previous_distance = current_distance

    except KeyboardInterrupt:
        print("Exiting gracefully...")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

