import time
import logging
import subprocess
from datetime import datetime
from gpiozero import DigitalOutputDevice
from random import uniform

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

def simulate_light_sensor():
    try:
        current_hour = datetime.now().hour
        if 6 <= current_hour < 18:
            return uniform(600, 1000)
        else:
            return uniform(100, 300)
    except Exception as e:
        logging.error(f"Error simulating light sensor: {e}")
        return 0

def simulate_temperature_sensor():
    try:
        return uniform(20, 30)
    except Exception as e:
        logging.error(f"Error simulating temperature sensor: {e}")
        return 0

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=2)
        if result.returncode == 0:
            temp_str = result.stdout.strip().split('=')[1].split("'")[0]
            return float(temp_str)
        else:
            logging.warning("Failed to read Pi temperature")
            return None
    except Exception as e:
        logging.warning(f"Error reading Pi temperature: {e}")
        return None

def calculate_voltage_and_current(lux):
    if lux > LOW_LIGHT_THRESHOLD:
        voltage = uniform(11.5, 12.5)
        current = uniform(1.5, 2.5)
    else:
        voltage = uniform(10.0, 11.0)
        current = uniform(0.5, 1.0)
    return voltage, current

def log_data(lux, temp, voltage, current, pi_temp):
    pi_temp_str = f"{pi_temp}°C" if pi_temp is not None else "N/A"
    logging.info(f"Light: {lux} lux, Temp: {temp}°C, Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp_str}")

def setup():
    # Setup GPIO devices if needed
    light_sensor = DigitalOutputDevice(LIGHT_SENSOR_PIN)
    temp_sensor = DigitalOutputDevice(TEMP_SENSOR_PIN)
    return light_sensor, temp_sensor

def main():
    light_sensor, temp_sensor = setup()
    try:
        while True:
            lux = simulate_light_sensor()
            temp = simulate_temperature_sensor()
            voltage, current = calculate_voltage_and_current(lux)
            pi_temp = read_pi_temperature()

            if lux < LOW_LIGHT_THRESHOLD:
                logging.warning("WARNING: Light level below threshold")
            if temp > HIGH_TEMP_THRESHOLD:
                logging.warning("WARNING: Temperature exceeds threshold, activating cooling")
            if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
                logging.critical("CRITICAL: Pi temperature exceeds threshold, simulating shutdown")
                break

            log_data(lux, temp, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Program terminated by user")
    finally:
        light_sensor.close()
        temp_sensor.close()

if __name__ == '__main__':
    main()

