DHT_PIN = 4  # GPIO4 (BCM)

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    time.sleep(0.02)  # Ensure the sensor is ready

def read_dht22():
    try:
        # Start signal
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.00004)
        GPIO.setup(DHT_PIN, GPIO.IN)

        # Wait for sensor response
        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() - start_time > 0.02:
                return None, None  # Timeout waiting for response

        while GPIO.input(DHT_PIN) == GPIO.LOW:
            pass

        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            pass

        # Read 40 bits
        data = []
        for _ in range(40):
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                pass

            pulse_start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                pass

            pulse_duration = time.time() - pulse_start
            if pulse_duration > 0.025:
                data.append(1)
            else:
                data.append(0)

        # Convert data to bytes
        bytes_data = []
        for i in range(0, 40, 8):
            byte = 0
            for j in range(8):
                byte |= (data[i + j] << (7 - j))
            bytes_data.append(byte)

        # Extract humidity, temperature, and checksum
        humidity = bytes_data[0] << 8 | bytes_data[1]
        temperature = bytes_data[2] << 8 | bytes_data[3]
        checksum = bytes_data[4]

        # Verify checksum
        if (humidity + temperature + bytes_data[4]) & 0xFF != checksum:
            return None, None

        # Convert to floats
        humidity = humidity / 10.0
        temperature = temperature / 10.0
        if temperature & 0x8000:
            temperature = -(temperature & 0x7FFF) / 10.0

        return temperature, humidity

    except Exception as e:
        print(f"Error reading DHT22: {e}")
        return None, None

