from gpiozero import PWMOutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory

# Initialize PWM on BCM pin 18 with a frequency of 50 Hz
pwm_pin = 18
pwm = PWMOutputDevice(pin=pwm_pin, frequency=50, pin_factory=PiGPIOFactory())

def get_cpu_temperature():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp_str = f.read().strip()
            return int(temp_str) / 1000.0  # Convert from millidegree Celsius to degree Celsius
    except FileNotFoundError:
        print("Error: Temperature file not found.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def compute_duty_cycle(temperature):
    # Example logic: linearly map temperature from 30°C to 80°C to duty cycle from 0.1 to 1.0
    min_temp, max_temp = 30.0, 80.0
    min_duty, max_duty = 0.1, 1.0
    if temperature < min_temp:
        return min_duty
    elif temperature > max_temp:
        return max_duty
    else:
        return min_duty + (max_duty - min_duty) * ((temperature - min_temp) / (max_temp - min_temp))

