            time.sleep(self.STATUS_POLL_INTERVAL)
        return False

    def _read_data(self):
        for attempt in range(self.MAX_ATTEMPTS):
            if not self._check_status():
                time.sleep(self.MEASUREMENT_RETRY_PAUSE)
                continue

            try:
                data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, self.DATA_REGISTER, 7)
                if self._crc_check(data):
                    return data[:6]
            except OSError as e:
                logger.warning(f"Data read failed: {e}")

            time.sleep(self.MEASUREMENT_RETRY_PAUSE)

        return None

