import time
import signal
import logging
from gpiozero import PWMOutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
import subprocess
import os

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

class FanController:
    def __init__(self, pwm_pin, frequency=100):
        self.pwm_pin = pwm_pin
        self.frequency = frequency
        self.fan = PWMOutputDevice(pin=self.pwm_pin, frequency=self.frequency, pin_factory=PiGPIOFactory())
        self.running = True

    def read_cpu_temperature(self):
        try:
            # Try reading from vcgencmd
            temp_output = subprocess.check_output(['vcgencmd', 'measure_temp']).decode()
            temp_str = temp_output.split('=')[1].split("'")[0]
            return float(temp_str)
        except Exception as e:
            logging.warning(f"Failed to read temperature using vcgencmd: {e}")

        try:
            # Fallback to reading from /sys/class/thermal
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                temp_raw = f.read().strip()
                return float(temp_raw) / 1000.0
        except Exception as e:
            logging.warning(f"Failed to read temperature from /sys/class/thermal: {e}")

        return None

    def compute_duty_cycle(self, temperature):
        if temperature is None:
            return 0.0

        # Define temperature thresholds and corresponding duty cycles
        if temperature < 40:
            return 0.0
        elif 40 <= temperature < 50:
            return 0.25
        elif 50 <= temperature < 60:
            return 0.5
        elif 60 <= temperature < 70:
            return 0.75
        else:
            return 1.0

    def run(self):
        while self.running:
            temperature = self.read_cpu_temperature()
            if temperature is not None:
                duty_cycle = self.compute_duty_cycle(temperature)
                self.fan.value = duty_cycle
                logging.info(f"Temperature: {temperature:.2f}°C, Fan Speed: {duty_cycle*100:.0f}%")
            else:
                logging.warning("Temperature read failed, setting fan speed to 0%")
                self.fan.value = 0.0

            time.sleep(5)

    def stop(self):
        self.running = False
        self.fan.close()

def signal_handler(signal, frame, controller):
    logging.info("Signal received, stopping fan controller...")
    controller.stop()

if __name__ == "__main__":
    controller = FanController(pwm_pin=14)

    # Setup signal handlers for clean exit
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, controller))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, controller))

    try:
        controller.run()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        controller.stop()
        logging.info("Fan controller stopped.")

