# Constants
BAUD_RATE = 9600
SERIAL_PORT = '/dev/ttyUSB0'
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_TIMEOUT = 2  # seconds

def read_sensor_data(ser):
    try:
        line = ser.readline().decode('utf-8').strip()
        if ',' in line:
            temperature, humidity = line.split(',')
            try:
                temperature = float(temperature)
                humidity = float(humidity)
                return temperature, humidity
            except ValueError:
                logging.error("Malformed line: %s", line)
        else:
            logging.error("Malformed line: %s", line)
    except Exception as e:
        logging.error("Error reading from sensor: %s", e)
    return None, None

def main():
    ser = None
    try:
        # Initialize UART connection
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        logging.info("UART connection established on %s at %d baud", SERIAL_PORT, BAUD_RATE)

        while True:
            temperature, humidity = read_sensor_data(ser)
            if temperature is not None and humidity is not None:
                logging.info("Temperature: %.1f, Humidity: %.1f", temperature, humidity)
                print(f"{temperature},{humidity}")

                # Check for alert conditions
                if temperature > TEMP_THRESHOLD:
                    logging.warning("Temperature alert: %.1f°C", temperature)
                if humidity > HUMIDITY_THRESHOLD:
                    logging.warning("Humidity alert: %.1f%%", humidity)

            time.sleep(1)  # Pause one second between readings

    except serial.SerialException as e:
        logging.error("Serial port error: %s", e)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        if ser and ser.is_open:
            ser.close()
            logging.info("UART connection closed")

if __name__ == "__main__":
    main()

