import matplotlib.animation as animation
from matplotlib.colors import Normalize
import time

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
FRAME_SIZE = 24 * 32
TIMEOUT = 0.1  # 100 ms timeout for reading
INTERVAL = 100  # 0.1 seconds for refreshing the display

# Initialize variables
last_good_frame = None

def parse_frame(data):
    try:
        # Split the data by commas and convert to integers
        values = list(map(int, data.split(',')))
        if len(values) == FRAME_SIZE:
            return np.array(values).reshape((24, 32))
    except ValueError:
        # Handle non-numeric tokens
        pass
    return None

def update_heatmap(frame, im):
    if frame is not None:
        im.set_data(frame)
        im.set_norm(Normalize(vmin=frame.min(), vmax=frame.max()))
    return im,

def main():
    global last_good_frame

    # Setup serial connection
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
        return

    # Setup matplotlib figure
    fig, ax = plt.subplots()
    im = ax.imshow(np.zeros((24, 32)), cmap='inferno', interpolation='nearest')
    plt.colorbar(im, ax=ax)

    def animate(i):
        global last_good_frame
        line = ser.readline().decode('utf-8').strip()
        if line:
            frame = parse_frame(line)
            if frame is not None:
                last_good_frame = frame
        return update_heatmap(last_good_frame, im)

    ani = animation.FuncAnimation(fig, animate, interval=INTERVAL)

    try:
        plt.show()
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        ser.close()
        plt.close(fig)

