def validate_reading(temperature, humidity):
    try:
        temp = float(temperature)
        hum = float(humidity)
        if 10 <= temp <= 55 and 20 <= hum <= 100:
            return temp, hum
        else:
            raise ValueError("Temperature or humidity out of valid range.")
    except (TypeError, ValueError) as e:
        logger.error(f"Validation error: {e}")
        return None, None

def simulate_dht22_reading():
    for _ in range(3):
        try:
