from vad import VoiceActivityDetector  # Assume this is a custom module
from keyword_spotting import KeywordSpotter  # Assume this is a custom module

# Configuration defaults
CONFIG_FILE = 'config.json'
DEFAULT_LED_PIN = 17
DEFAULT_HEARTBEAT_INTERVAL = 60
DEFAULT_UPDATE_INTERVAL = 300
DEFAULT_LOG_INTERVAL = 60

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
config = {}
led = None
mqtt_client_instance = None
shutdown_event = Event()

def load_config():
    global config
    try:
        with open(CONFIG_FILE, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file {CONFIG_FILE} not found. Using default settings.")
        config = {
            "sensitivity": 0.5,
            "keywords": ["hello", "test"],
            "sentiment_threshold": 0.2,
            "led_pin": DEFAULT_LED_PIN,
            "heartbeat_interval": DEFAULT_HEARTBEAT_INTERVAL,
            "update_interval": DEFAULT_UPDATE_INTERVAL,
            "log_interval": DEFAULT_LOG_INTERVAL,
            "mqtt": {
                "broker": "mqtt.example.com",
                "port": 1883,
                "topic": "alerts"
            }
        }
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON: {e}")
        sys.exit(1)

def setup_led():
    global led
    led = LED(config.get("led_pin", DEFAULT_LED_PIN))

def setup_mqtt():
    global mqtt_client_instance
    mqtt_client_instance = mqtt_client.Client()
    mqtt_client_instance.connect(config["mqtt"]["broker"], config["mqtt"]["port"])

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down...")
    shutdown_event.set()

@contextmanager
def audio_stream():
    try:
        stream = sd.InputStream(samplerate=16000, channels=1, callback=audio_callback)
        with stream:
            yield
    except Exception as e:
        logging.error(f"Audio device error: {e}")
    finally:
        stream.close()

def audio_callback(indata, frames, time, status):
    if status:
        logging.warning(f"Audio callback status: {status}")
    queue.put(indata.copy())

def voice_activity_detection(data):
    vad = VoiceActivityDetector(sensitivity=config["sensitivity"])
    return vad.is_speech(data)

def keyword_spotting(data):
    spotter = KeywordSpotter(config["keywords"])
    return spotter.detect(data)

def sentiment_analysis(data):
    analyzer = SentimentAnalyzer()
    sentiment = analyzer.analyze(data)
    return sentiment

def check_sentiment(sentiment):
    if sentiment < config["sentiment_threshold"]:
        led.on()
        if mqtt_client_instance:
            mqtt_client_instance.publish(config["mqtt"]["topic"], "Negative sentiment detected")
    else:
        led.off()

def heartbeat():
    while not shutdown_event.is_set():
        logging.info("Heartbeat signal")
        time.sleep(config["heartbeat_interval"])

def check_for_updates():
    while not shutdown_event.is_set():
        time.sleep(config["update_interval"])
        load_config()
        logging.info("Configuration updated")

def log_resource_usage():
    while not shutdown_event.is_set():
        logging.info("Logging resource usage")
        # Implement resource usage logging here
        time.sleep(config["log_interval"])

def main():
    load_config()
    setup_led()
    setup_mqtt()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    queue = Queue()

    with audio_stream():
        threads = [
            Thread(target=heartbeat),
            Thread(target=check_for_updates),
            Thread(target=log_resource_usage)
        ]

        for thread in threads:
            thread.start()

        try:
            while not shutdown_event.is_set():
                try:
                    data = queue.get(timeout=1)
                    if voice_activity_detection(data):
                        if keyword_spotting(data):
                            logging.info("Keyword detected")
                        sentiment = sentiment_analysis(data)
                        check_sentiment(sentiment)
                except Empty:
                    continue
        finally:
            shutdown_event.set()
            for thread in threads:
                thread.join()
            if mqtt_client_instance:
                mqtt_client_instance.disconnect()

if __name__ == "__main__":
    main()

import time
import signal
import sys
from datetime import datetime
from gpiozero import DigitalInputDevice
from contextlib import contextmanager

class OccupancyMonitor:
    def __init__(self, gpio_pin=17, debounce_interval=2.0, sample_count=10):
        self.gpio_pin = gpio_pin
        self.debounce_interval = debounce_interval
        self.sample_count = sample_count
        self.motion_detected = False
        self.last_detection_time = 0
        self.detection_events = []
        self.sensor = None

    def initialize_sensor(self):
        try:
            self.sensor = DigitalInputDevice(pin=self.gpio_pin, pull_up=True)
        except Exception as e:
            print(f"Failed to initialize sensor: {e}")
            sys.exit(1)

    def poll_sensor(self):
        while True:
            try:
                if self.sensor.is_active:
                    current_time = time.time()
                    if not self.motion_detected and (current_time - self.last_detection_time) >= self.debounce_interval:
                        self.motion_detected = True
                        self.last_detection_time = current_time
                        timestamp = datetime.now().isoformat()
                        self.detection_events.append(timestamp)
                        print(f"Motion detected at {timestamp}")
                else:
                    self.motion_detected = False

                if len(self.detection_events) >= self.sample_count:
                    break

                time.sleep(0.5)
            except Exception as e:
                print(f"Runtime error: {e}")
                break

    def get_occupancy_statistics(self):
        return {
            "total_events": len(self.detection_events),
            "events": self.detection_events
        }

    def print_summary_report(self):
        stats = self.get_occupancy_statistics()
        print("\nSummary Report:")
        print(f"Total number of events: {stats['total_events']}")
        for event in stats['events']:
            print(f"Event at: {event}")

    def cleanup(self):
        if self.sensor:
            self.sensor.close()

@contextmanager
def handle_signals():
    def signal_handler(signum, frame):
        print(f"Received signal {signum}, exiting gracefully.")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        yield
    finally:
        pass

def main():
    monitor = OccupancyMonitor()
    monitor.initialize_sensor()

    with handle_signals():
        monitor.poll_sensor()

    monitor.print_summary_report()
    monitor.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    main()

