import logging
import signal
import time
import zmq
from gpiozero import PWMOutputDevice, DigitalOutputDevice
from gpiozero.pins.mock import MockFactory

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class PIDHandler:
    def __init__(self, pwm=True):
        self.pwm = pwm
        self.global_err_state = False
        self.last_msg = time.time()
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.socket.setsockopt_string(zmq.SUBSCRIBE, '')
        self.socket.connect("tcp://localhost:5555")
        self.callbacks = []

        # Initialize GPIO
        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(12, pin_factory=MockFactory())
            else:
                self.error_output = DigitalOutputDevice(10, pin_factory=MockFactory())
            self.error_output.frequency = 1000
            self.error_output.value = 0.0
        except Exception as e:
            logger.error("Failed to initialize GPIO: %s", e)
            self.cleanup()
            raise

        # Setup signal handlers
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def update_error_output(self):
        self.set_error_output(self.global_err_state)

    def set_error_output(self, state: bool):
        try:
            if self.pwm:
                self.error_output.value = 1.0 if state else 0.0
            else:
                self.error_output.value = state
        except Exception as e:
            logger.error("Failed to set error output: %s", e)

    def handle_message(self):
        try:
            if self.socket.poll(1000, zmq.POLLIN):
                message = self.socket.recv_string()
                self.last_msg = time.time()
                for callback in self.callbacks:
                    callback(message)
            else:
                self.watchdog_check()
        except Exception as e:
            logger.error("Error handling message: %s", e)

    def watchdog_check(self):
        if time.time() - self.last_msg > 20:
            self.set_error_output(True)

    def register_callback(self, callback):
        self.callbacks.append(callback)

    def cleanup(self):
        try:
            self.error_output.close()
            self.socket.close()
            self.context.term()
            logger.info("Resources cleaned up successfully.")
        except Exception as e:
            logger.error("Error during cleanup: %s", e)

    def signal_handler(self, signum, frame):
        logger.info("Signal %d received, cleaning up...", signum)
        self.cleanup()
        exit(0)

if __name__ == "__main__":
    try:
        pid_handler = PIDHandler(pwm=True)
        while True:
            pid_handler.handle_message()
            time.sleep(0.1)
    except Exception as e:
        logger.error("An error occurred: %s", e)
    finally:
        pid_handler.cleanup()

