from contextlib import contextmanager

# Setup logging
logging.basicConfig(filename='notification_light.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
HOST = '192.168.1.100'
PORT = 5000
RECONNECT_BACKOFF_START = 1
RECONNECT_BACKOFF_MAX = 60

# GPIO pin setup
led_pins = {
    'cpu': {'red': 17, 'green': 18, 'blue': 27},
    'memory': {'red': 22, 'green': 23, 'blue': 24},
    'disk_io': {'red': 5, 'green': 6, 'blue': 13}
}

# Initialize PWM LEDs
leds = {key: {color: PWMLED(pin) for color, pin in value.items()} for key, value in led_pins.items()}

# Lock for shared data
data_lock = threading.Lock()
data = {'cpu_usage': 0.0, 'memory_usage': 0.0, 'disk_io': 0.0}

def cleanup():
    logging.info("Cleaning up resources.")
    for key in leds:
        for color in leds[key]:
            leds[key][color].close()
    if 'sock' in globals():
        sock.close()
    logging.info("Cleanup complete.")

def signal_handler(signum, frame):
    logging.info(f"Received signal {signum}, shutting down.")
    cleanup()
    exit(0)

def setup_signal_handlers():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

def map_value(value):
    if value > 66:
        return (1, 0, 0)  # Red
    elif value > 33:
        return (0, 1, 0)  # Green
    else:
        return (0, 0, 1)  # Blue

def update_leds():
    with data_lock:
        cpu_usage = data['cpu_usage']
        memory_usage = data['memory_usage']
        disk_io = data['disk_io']

    def set_led(usage, led):
        r, g, b = map_value(usage)
        leds[led]['red'].value = r
        leds[led]['green'].value = g
        leds[led]['blue'].value = b

    set_led(cpu_usage, 'cpu')
    set_led(memory_usage, 'memory')
    set_led(disk_io, 'disk_io')

def receive_data():
    global sock
    backoff = RECONNECT_BACKOFF_START

    while True:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((HOST, PORT))
            logging.info("Connected to server.")
            backoff = RECONNECT_BACKOFF_START  # Reset backoff on successful connection

            while True:
                try:
                    data = sock.recv(1024)
                    if not data:
                        raise ConnectionError("Connection closed by server.")

                    json_data = json.loads(data.decode('utf-8'))
                    with data_lock:
                        if all(0 <= json_data[key] <= 100 for key in json_data):
                            data.update(json_data)
                        else:
                            logging.warning("Received out-of-range data: %s", json_data)

                    update_leds()

                except json.JSONDecodeError:
                    logging.error("JSON decode error.")
                except socket.error as e:
                    logging.error("Socket error: %s", e)
                    break

        except (socket.error, ConnectionError) as e:
            logging.error("Connection error: %s", e)
            time.sleep(backoff)
            backoff = min(backoff * 2, RECONNECT_BACKOFF_MAX)

        finally:
            if 'sock' in globals():
                sock.close()
                logging.info("Socket closed.")

def main():
    setup_signal_handlers()

    try:
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()

        while True:
            time.sleep(1)

    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

