import argparse
import random
import time
import datetime
from gpiozero import DigitalOutputDevice, DigitalInputDevice
from signal import signal, SIGINT

def parse_arguments():
    parser = argparse.ArgumentParser(description="Monitor rainwater harvesting tank.")
    parser.add_argument("--tank_height", type=float, required=True, help="Height of the tank in cm.")
    parser.add_argument("--tank_diameter", type=float, required=True, help="Diameter of the tank in cm.")
    parser.add_argument("--simulate", action="store_true", help="Simulate sensor readings.")
    return parser.parse_args()

def setup_gpio(trigger_pin, echo_pin):
    trigger = DigitalOutputDevice(trigger_pin, active_high=False, initial_value=False)
    echo = DigitalInputDevice(echo_pin)
    return trigger, echo

def measure_distance(trigger, echo, timeout=1):
    try:
        trigger.on()
        time.sleep(0.00001)  # 10 µs
        trigger.off()

        start_time = time.time()
        while not echo.is_active and (time.time() - start_time) < timeout:
            pass

        if echo.is_active:
            start_time = time.time()
            while echo.is_active and (time.time() - start_time) < timeout:
                pass
            end_time = time.time()

            if (end_time - start_time) < timeout:
                distance = (end_time - start_time) * 34300 / 2  # Speed of sound in cm/s
                return distance
    except Exception as e:
        print(f"Error measuring distance: {e}")
    return None

def validate_distance(distance):
    return 2 <= distance <= 400

def calculate_water_level(top_distance, bottom_distance):
    return bottom_distance - top_distance

def calculate_volume(water_level, tank_diameter):
    radius = tank_diameter / 2
    return 3.14159 * (radius ** 2) * water_level

def simulate_distance():
    return random.uniform(10, 90)

def cleanup(triggers, echoes):
    for trigger, echo in zip(triggers, echoes):
        trigger.close()
        echo.close()

def main():
    args = parse_arguments()

    if args.tank_height <= 0 or args.tank_diameter <= 0:
        raise ValueError("Tank height and diameter must be positive values.")

    trigger1, echo1 = setup_gpio(17, 18)
    trigger2, echo2 = setup_gpio(22, 23)
    triggers = [trigger1, trigger2]
    echoes = [echo1, echo2]

    def signal_handler(sig, frame):
        print("Exiting gracefully...")
        cleanup(triggers, echoes)
        exit(0)

    signal(SIGINT, signal_handler)

    try:
        while True:
            if args.simulate:
                top_distance = simulate_distance()
                bottom_distance = simulate_distance()
            else:
                top_distance = measure_distance(trigger1, echo1)
                bottom_distance = measure_distance(trigger2, echo2)

            if top_distance is not None and bottom_distance is not None:
                if validate_distance(top_distance) and validate_distance(bottom_distance):
                    water_level = calculate_water_level(top_distance, bottom_distance)
                    volume = calculate_volume(water_level, args.tank_diameter)

                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    print(f"{timestamp} - Top Distance: {top_distance:.2f} cm, Bottom Distance: {bottom_distance:.2f} cm, "
                          f"Water Level: {water_level:.2f} cm, Volume: {volume:.2f} cm³")

                    # Simulated cloud-send message
                    print(f"Simulated cloud-send: Water Level: {water_level:.2f} cm, Volume: {volume:.2f} cm³")
                else:
                    print("Invalid distance reading.")
            else:
                print("Error reading sensor data.")

            time.sleep(5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup(triggers, echoes)

if __name__ == "__main__":
    main()

