import logging
import random
import time
from gpiozero import MotionSensor
from gpiozero.exc import GPIOPinInUseError, PinFactoryError
from signal import signal, SIGINT
from contextlib import contextmanager

# Configure logging
logging.basicConfig(
    filename='art_installation.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Simulated actuator functions
def activate_light():
    logging.info("Light activated")
    print("Light activated")

def activate_sound():
    logging.info("Sound activated")
    print("Sound activated")

def activate_motor():
    logging.info("Motor activated")
    print("Motor activated")

ACTUATORS = [activate_light, activate_sound, activate_motor]

# Context manager for GPIO cleanup
@contextmanager
def gpio_cleanup():
    try:
        yield
    finally:
        logging.info("Cleaning up GPIO resources")
        MotionSensor.cleanup()

def read_sensor(sensor):
    try:
        return sensor.is_active
    except Exception as e:
        logging.error(f"Error reading sensor: {e}")
        return None

def main():
    try:
        # Initialize GPIO
        with gpio_cleanup():
            sensor1 = MotionSensor(17, pull_up=True)
            sensor2 = MotionSensor(18, pull_up=True)

            last_trigger_time = None

            while True:
                try:
                    sensor1_triggered = not read_sensor(sensor1)
                    sensor2_triggered = not read_sensor(sensor2)

                    if sensor1_triggered or sensor2_triggered:
                        current_time = time.time()

                        if last_trigger_time and (current_time - last_trigger_time) < 0.5:
                            logging.warning("Confirmed Intrusion")
                            for actuator in ACTUATORS:
                                actuator()
                        else:
                            if sensor1_triggered:
                                logging.info(f"Intrusion Detected - Sensor 1 on GPIO 17")
                            if sensor2_triggered:
                                logging.info(f"Intrusion Detected - Sensor 2 on GPIO 18")

                            actuator = random.choice(ACTUATORS)
                            actuator()

                        last_trigger_time = current_time
                        time.sleep(0.1)  # Debounce

                    time.sleep(0.05)  # Loop iteration delay

                except Exception as e:
                    logging.error(f"Unexpected error: {e}")
                    # Decide whether to continue or exit
                    # For this example, we'll continue
                    continue

    except (GPIOPinInUseError, PinFactoryError) as e:
        logging.error(f"GPIO initialization error: {e}")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unhandled exception: {e}")

if __name__ == "__main__":
    main()

