from gpiozero import LED
from gpiozero.exc import GPIOZeroError
import signal

# Function to handle cleanup on exit
def cleanup(led):
    try:
        led.close()
    except Exception as e:
        print(f"Error during cleanup: {e}")

# Function to simulate a water quality reading
def read_water_quality():
    if random.random() < 0.1:  # 10% chance of failure
        raise ValueError("Sensor read failure")
    return random.randint(0, 100)

def main():
    led = None
    try:
        # Validate GPIO setup
        led = LED(18, active_high=False, resistor=330)

        # Register cleanup function to handle exit paths
        signal.signal(signal.SIGINT, lambda signum, frame: cleanup(led))

        for i in range(5):
            try:
                reading = read_water_quality()
                print(f"Reading {i+1}: {reading}%")

                if reading < 50:
                    led.on()
                    print("LED is ON (Alert: Poor water quality)")
                else:
                    led.off()
                    print("LED is OFF (Water quality is acceptable)")

                time.sleep(2)
            except ValueError as e:
                print(f"Error: {e}. Retrying...")
                try:
                    reading = read_water_quality()
                    print(f"Retried Reading {i+1}: {reading}%")

                    if reading < 50:
                        led.on()
                        print("LED is ON (Alert: Poor water quality)")
                    else:
                        led.off()
                        print("LED is OFF (Water quality is acceptable)")
                except ValueError as retry_error:
                    print(f"Retry failed: {retry_error}. Skipping this reading.")

    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup(led)

if __name__ == "__main__":
    main()

