import logging
import signal
import atexit
from adafruit_pca9685 import PCA9685
from adafruit_motor import servo
import board
import busio
import time

# Configure logging
logging.basicConfig(level=logging.INFO)

class DCMotorHATExtra:
    def __init__(self, i2c_bus):
        self.i2c_bus = i2c_bus
        try:
            self.pca = PCA9685(i2c_bus)
            logging.info("DCMotorHATExtra initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize DCMotorHATExtra: {e}")
            raise

    def set_pwm_freq(self, freq):
        self.pca.frequency = freq

    def stop(self):
        self.pca.deinit()

class DCMotor:
    def __init__(self, hat, motor_number, pwm_freq=60, invert=False):
        if motor_number < 1 or motor_number > 4:
            raise ValueError("Motor number must be between 1 and 4.")

        self.hat = hat
        self.motor_number = motor_number
        self.pwm_freq = pwm_freq
        self.invert = invert
        self.last_duty_cycle = 0

        self.hat.set_pwm_freq(self.pwm_freq)
        self.servo = servo.Servo(self.hat.channels[motor_number - 1])
        self.servo.frequency = self.pwm_freq

    def set_pwm_freq(self, freq):
        self.pwm_freq = freq
        self.hat.set_pwm_freq(freq)
        self.servo.frequency = freq

    def get_pwm_freq(self):
        return self.pwm_freq

    def set_dc(self, duty_cycle):
        if not (-255 <= duty_cycle <= 255):
            logging.warning("Duty cycle out of range, clamping to -255 to 255.")
            duty_cycle = max(-255, min(255, duty_cycle))

        if duty_cycle == self.last_duty_cycle:
            return

        direction = (duty_cycle < 0) ^ self.invert
        speed = abs(duty_cycle)

        try:
            if direction:
                self.servo.throttle = -speed / 255.0
            else:
                self.servo.throttle = speed / 255.0
            self.last_duty_cycle = duty_cycle
        except Exception as e:
            logging.error(f"Error setting duty cycle: {e}")

    def stop(self):
        self.set_dc(0)

    def get_status(self):
        return {
            "motor_number": self.motor_number,
            "pwm_freq": self.pwm_freq,
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }

def cleanup(motors):
    logging.info("Cleaning up motors.")
    for motor in motors:
        motor.stop()
    motors[0].hat.stop()

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down.")
    cleanup(motors)
    exit(0)

def main():
    global motors

    try:
        i2c_bus = busio.I2C(board.SCL1, board.SDA1)
        hat = DCMotorHATExtra(i2c_bus)
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus or DCMotorHATExtra: {e}")
        return

    motors = [
        DCMotor(hat, 1),
        DCMotor(hat, 2),
        DCMotor(hat, 3),
        DCMotor(hat, 4)
    ]

    atexit.register(cleanup, motors)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Usage example
    motor = motors[0]
    logging.info("Ramping motor forward.")
    for dc in range(0, 256, 5):
        motor.set_dc(dc)
        time.sleep(0.05)

    logging.info("Ramping motor backward.")
    for dc in range(255, -256, -5):
        motor.set_dc(dc)
        time.sleep(0.05)

    logging.info("Stopping motor.")
    motor.stop()

if __name__ == "__main__":
    main()

