    with cleanup_on_exit(left_sensor, right_sensor, left_motor, right_motor):
        for _ in range(20):
            try:
                left_reading = left_sensor.value
                right_reading = right_sensor.value

                if left_reading and right_reading:
                    # Both sensors detect the line, go straight
                    left_motor.forward()
                    right_motor.forward()
                elif left_reading:
                    # Only left sensor detects the line, turn left
                    left_motor.stop()
                    right_motor.forward()
                elif right_reading:
