import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass

class Motor:
    def __init__(self, driver, pin):
        self.driver = driver
        self.pin = pin
        self.device = None

        try:
            # Set up the GPIO pin
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)

            # Initialize PWMOutputDevice
            self.device = PWMOutputDevice(pin=self.pin, frequency=1000)
            self.device.value = 0  # Set initial duty cycle to 0

        except (GPIOZeroError, RuntimeError) as e:
            raise MotorError(f"Failed to initialize motor on pin {self.pin}: {e}")

    def set_frequency(self, freq):
        try:
            self.device.frequency = freq
