import logging
import time
import signal
import sys
from gpiozero import Servo
from gpiozero.pins.pigpio import PiGPIOFactory

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

class ServoController:
    def __init__(self, pin=18):
        self.pin = pin
        self.servo = None
        self._setup_servo()

    def _setup_servo(self):
        try:
            self.servo = Servo(self.pin, pin_factory=PiGPIOFactory())
        except Exception as e:
            logging.error(f"Failed to initialize servo on GPIO {self.pin}: {e}")
            raise

    def _angle_to_duty_cycle(self, angle):
        # Convert angle to duty cycle for SG90 servo
        # SG90 typically operates between 0.5ms (0°) and 2.5ms (180°) pulse width
        # Duty cycle is calculated as pulse width / period
        # Period for 50Hz is 20ms, so duty cycle range is 0.025 to 0.125
        return 0.025 + (angle / 180.0) * 0.1

    def move_to(self, angle):
        try:
            duty_cycle = self._angle_to_duty_cycle(angle)
            self.servo.value = duty_cycle
            logging.info(f"Moved to angle: {angle} degrees")
            time.sleep(0.5)
        except Exception as e:
            logging.error(f"Failed to move servo to angle {angle}: {e}")

    def stop(self):
        if self.servo:
            self.servo.close()
            logging.info("Servo stopped and resources released.")

def signal_handler(sig, frame):
    logging.info("Interrupt received, stopping servo.")
    servo_controller.stop()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        servo_controller = ServoController()

        angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
        for angle in angles:
            servo_controller.move_to(angle)

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        servo_controller.stop()

if __name__ == "__main__":
    main()

