    try:
        relay.off()
        time.sleep(1)
        logging.info("Door opened.")
    except GPIOError as e:
        logging.error(f"Error opening door: {e}")

def close_door():
    try:
        relay.on()
        time.sleep(1)
        logging.info("Door closed.")
    except GPIOError as e:
