import logging
import signal
import time
from datetime import datetime
from gpiozero import OutputDevice, DigitalOutputDevice
from gpiozero.pins.bcm import BCMGPIO

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

class SolenoidController:
    def __init__(self, pin=24):
        self.pin = pin
        self.relay = None
        self.setup_relay()

    def setup_relay(self):
        try:
            self.relay = DigitalOutputDevice(pin=self.pin, active_high=False, pin_factory=BCMGPIO())
            if self.relay.value:
                raise RuntimeError("Relay is already active on initialization.")
        except Exception as e:
            logging.error(f"Failed to set up relay: {e}")
            raise

    def pulse(self, duration=0.4, delay=1.0, count=3):
        try:
            for i in range(1, count + 1):
                if self.relay.value:
                    logging.warning("Relay is already active. Skipping pulse.")
                    continue
                logging.info(f"Activating pulse {i}")
                self.relay.on()
                time.sleep(duration)
                self.relay.off()
                logging.info(f"Deactivating pulse {i}")
                time.sleep(delay)
        except Exception as e:
            logging.error(f"Error during pulse operation: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.relay:
            self.relay.off()
            self.relay.close()
            logging.info("Relay cleaned up and closed.")

def signal_handler(sig, frame):
    logging.info("Signal received, exiting...")
    controller.cleanup()
    exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        controller = SolenoidController()
        controller.pulse()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        controller.cleanup()

if __name__ == "__main__":
    main()

