import logging
import time
from paho.mqtt import client as mqtt_client
from paho.mqtt import exceptions as mqtt_exceptions

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Classification counts
classification_counts = {
    'noise': 0,
    'traffic': 0,
    'other': 0
}

def classify_report(report_text):
    """Classify the report text into categories: noise, traffic, or other."""
    report_text = report_text.lower()
    if 'noise' in report_text:
        return 'noise'
    elif 'traffic' in report_text or 'car' in report_text or 'vehicle' in report_text:
        return 'traffic'
    else:
        return 'other'

def handle_message(mqtt_client, userdata, message):
    """Handle incoming MQTT messages."""
    try:
        report_text = message.payload.decode('utf-8')
        category = classify_report(report_text)
        classification_counts[category] += 1
        logging.info(f"Report classified as {category}: {report_text}")
    except (AttributeError, UnicodeDecodeError) as e:
        logging.error(f"Decode error: {e}")

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        logging.info("Connected to MQTT Broker!")
        client.subscribe("city/reports")
    else:
        logging.error(f"Failed to connect, return code {rc}")

def on_disconnect(client, userdata, rc):
    if rc != 0:
        logging.error("Unexpected disconnection.")

def main():
    broker = 'localhost'
    port = 1883
    topic = "city/reports"
    client_id = f'python-mqtt-{time.time()}'

    client = mqtt_client.Client(client_id, protocol=mqtt_client.MQTTv311)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_message = handle_message

    try:
        client.connect(broker, port)
    except mqtt_exceptions.MQTTException as e:
        logging.error(f"Connection error: {e}")
        return

    client.loop_start()

    try:
        time.sleep(5)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        client.loop_stop()
        client.disconnect()
        logging.info("MQTT client disconnected.")

    logging.info(f"Final classification counts: {classification_counts}")

if __name__ == '__main__':
    main()

import smbus2
from contextlib import contextmanager

class I2CDeviceHelper:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number
        self.bus = None
        self._open_bus()
        self._probe_device()

    def _open_bus(self):
        try:
            self.bus = smbus2.SMBus(self.bus_number)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to open I2C bus {self.bus_number}: {e}")

    def _probe_device(self):
        try:
            self.bus.write_quick(self.address)
        except (OSError, IOError) as e:
            self._close_bus()
            raise RuntimeError(f"Device at address {self.address} did not acknowledge: {e}")

    def write_byte(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to write byte to register {register}: {e}")

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to read byte from register {register}: {e}")

    def close(self):
        self._close_bus()

    def _close_bus(self):
        if self.bus:
            try:
                self.bus.close()
            except (OSError, IOError):
                pass
            finally:
                self.bus = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

