import signal
import sys
import time
from datetime import datetime
import smbus2
import logging

# Constants
DS1338_ADDRESS = 0x68
RTC_REG_SECONDS = 0x00
RTC_REG_MINUTES = 0x01
RTC_REG_HOURS = 0x02
RTC_REG_DAY = 0x03
RTC_REG_DATE = 0x04
RTC_REG_MONTH = 0x05
RTC_REG_YEAR = 0x06

# Setup logging
logging.basicConfig(level=logging.INFO)

# I2C bus setup
bus = smbus2.SMBus(1)

def signal_handler(sig, frame):
    logging.info("Exiting gracefully...")
    bus.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def bcd_to_int(bcd):
    return (bcd & 0x0F) + ((bcd >> 4) * 10)

def int_to_bcd(value):
    return ((value // 10) << 4) + (value % 10)

def verify_rtc():
    try:
        bus.write_byte(DS1338_ADDRESS, 0x00)  # Dummy write to check presence
        return True
    except OSError:
        logging.error("DS1338 RTC not found.")
        return False

def read_register(register):
    try:
        return bus.read_byte_data(DS1338_ADDRESS, register)
    except OSError as e:
        logging.error(f"Failed to read register {register}: {e}")
        return None

def write_register(register, value):
    try:
        bus.write_byte_data(DS1338_ADDRESS, register, value)
    except OSError as e:
        logging.error(f"Failed to write register {register}: {e}")

def read_datetime(century=21):
    try:
        seconds = bcd_to_int(read_register(RTC_REG_SECONDS))
        minutes = bcd_to_int(read_register(RTC_REG_MINUTES))
        hours = bcd_to_int(read_register(RTC_REG_HOURS)) & 0x3F  # Mask bit 6
        day = bcd_to_int(read_register(RTC_REG_DAY))
        date = bcd_to_int(read_register(RTC_REG_DATE))
        month = bcd_to_int(read_register(RTC_REG_MONTH))
        year = bcd_to_int(read_register(RTC_REG_YEAR))
        year += century * 100

        return datetime(year, month, date, hours, minutes, seconds)
    except Exception as e:
        logging.error(f"Failed to read datetime: {e}")
        return None

def write_all(seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
    try:
        if seconds is not None:
            write_register(RTC_REG_SECONDS, int_to_bcd(seconds))
        if minutes is not None:
            write_register(RTC_REG_MINUTES, int_to_bcd(minutes))
        if hours is not None:
            hours &= 0x3F  # Clear bit 6 for 24-hour format
            write_register(RTC_REG_HOURS, int_to_bcd(hours))
        if day is not None:
            write_register(RTC_REG_DAY, int_to_bcd(day))
        if date is not None:
            write_register(RTC_REG_DATE, int_to_bcd(date))
        if month is not None:
            write_register(RTC_REG_MONTH, int_to_bcd(month))
        if year is not None:
            year %= 100  # Only store the last two digits
            write_register(RTC_REG_YEAR, int_to_bcd(year))
    except Exception as e:
        logging.error(f"Failed to write datetime: {e}")

def main():
    if not verify_rtc():
        sys.exit(1)

    # Example usage
    logging.info("Current datetime from RTC:")
    dt = read_datetime()
    if dt:
        logging.info(dt)

    logging.info("Writing new datetime to RTC...")
    write_all(seconds=30, minutes=45, hours=14, day=3, date=15, month=10, year=23)
    time.sleep(1)

    logging.info("Updated datetime from RTC:")
    dt = read_datetime()
    if dt:
        logging.info(dt)

if __name__ == "__main__":
    try:
        main()
    finally:
        bus.close()

