import sys
import time
from datetime import datetime, timezone
import smbus2
import logging

class DS1338RTC:
    DEVICE_ADDRESS = 0x68
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, bus_number=1):
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
        except Exception as e:
            raise IOError(f"Failed to open I2C bus {bus_number}: {e}")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def close(self):
        if self.bus:
            self.bus.close()

    def _read_register(self, register):
        try:
            return self.bus.read_byte_data(self.DEVICE_ADDRESS, register)
        except Exception as e:
            raise IOError(f"Failed to read register {register:#04x}: {e}")

    def _write_register(self, register, value):
        try:
            self.bus.write_byte_data(self.DEVICE_ADDRESS, register, value)
        except Exception as e:
            raise IOError(f"Failed to write register {register:#04x}: {e}")

    def read_all(self):
        try:
            seconds = self._read_register(self.REG_SECONDS) & 0x7F  # Mask CH bit
            minutes = self._read_register(self.REG_MINUTES)
            hours = self._read_register(self.REG_HOURS) & 0x3F  # Mask 12/24-hour bit
            day = self._read_register(self.REG_DAY)
            date = self._read_register(self.REG_DATE)
            month = self._read_register(self.REG_MONTH)
            year = self._read_register(self.REG_YEAR) + 2000

            return (
                self._bcd_to_dec(year),
                self._bcd_to_dec(month),
                self._bcd_to_dec(date),
                self._bcd_to_dec(day),
                self._bcd_to_dec(hours),
                self._bcd_to_dec(minutes),
                self._bcd_to_dec(seconds)
            )
        except IOError as e:
            logging.error(e)
            raise

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (1 <= day <= 7):
            raise ValueError("Day must be between 1 and 7")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")

        self._write_register(self.REG_SECONDS, self._dec_to_bcd(seconds) & 0x7F)  # Clear CH bit
        self._write_register(self.REG_MINUTES, self._dec_to_bcd(minutes))
        self._write_register(self.REG_HOURS, self._dec_to_bcd(hours) & 0x3F)  # 24-hour mode
        self._write_register(self.REG_DAY, self._dec_to_bcd(day))
        self._write_register(self.REG_DATE, self._dec_to_bcd(date))
        self._write_register(self.REG_MONTH, self._dec_to_bcd(month))
        self._write_register(self.REG_YEAR, self._dec_to_bcd(year - 2000))

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.isoweekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.now(timezone.utc))

    @staticmethod
    def _bcd_to_dec(value):
        return (value & 0x0F) + ((value >> 4) * 10)

    @staticmethod
    def _dec_to_bcd(value):
        return ((value // 10) << 4) + (value % 10)

if __name__ == "__main__":
    try:
        with DS1338RTC() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current time: {current_time}")
    except IOError as e:
        sys.stderr.write(f"Error: {e}\n")
        sys.exit(0)
    except Exception as e:
        sys.stderr.write(f"Unexpected error: {e}\n")
        sys.exit(1)
