class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        self._open_serial_port()

    def _open_serial_port(self):
        try:
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baud_rate,
                timeout=self.timeout
            )
        except SerialException as e:
            print(f"Failed to open serial port: {e}")
            sys.exit(1)

    def _send_command(self, command, response_timeout=1.0):
        try:
            self.serial.write((command + '\r\n').encode())
            response = b''
            start_time = time.time()
            while time.time() - start_time < response_timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                if b'OK' in response or b'ERROR' in response or b'FAIL' in response:
                    break
            return response
        except SerialException as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT')
        return b'OK' in response

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password, timeout=10.0):
        command = f'AT+CWJAP="{ssid}","{password}"'
        response = self._send_command(command, response_timeout=timeout)
        return b'OK' in response

    def disconnect_wifi(self):
        return self._send_command('AT+CWQAP')

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response:
            lines = response.split(b'\r\n')
            for line in lines:
                if b'IP' in line:
                    return line.split(b':')[1].strip()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        header_str = '\r\n'.join(f'{k}: {v}' for k, v in headers.items())
        request = f'{method} {url} HTTP/1.1\r\nHost: {host}\r\n{header_str}\r\n\r\n{data or ""}'
        self._send_command(f'AT+CIPSTART="TCP","{host}",{port}')
        self._send_command(f'AT+CIPSEND={len(request)}')
        self._send_command(request)
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            if self.serial.in_waiting > 0:
                response += self.serial.read(self.serial.in_waiting)
                if b'+IPD,' in response:
                    parts = response.split(b'+IPD,')
                    for part in parts[1:]:
                        length_end = part.find(b':')
                        if length_end != -1:
                            length = int(part[:length_end])
                            data = part[length_end + 1:length_end + 1 + length]
                            return data
                if b'CLOSED' in response:
                    return None
        return response

    def close(self):
        if self.serial and self.serial.is_open:
            self.serial.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    controller.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with ESP8266Controller() as controller:
        if controller.test_connection():
            print("ESP8266 is connected.")
            if controller.restart():
                print("ESP8266 restarted successfully.")
            if controller.connect_wifi('your_ssid', 'your_password'):
                print("Connected to Wi-Fi.")
                ip = controller.get_ip()
                if ip:
                    print(f"IP Address: {ip.decode()}")
                response = controller.send_http_request('GET', '/', 'example.com')
                if response:
                    print(f"HTTP Response: {response.decode()}")
                controller.disconnect_wifi()
            else:
                print("Failed to connect to Wi-Fi.")
        else:
            print("Failed to test connection.")

