import serial
import time
import sys
from gpiozero import OutputDevice
from contextlib import contextmanager

# Context manager to handle serial port and GPIO cleanup
@contextmanager
def resource_manager(serial_port, alarm_pin):
    try:
        yield
    finally:
        if serial_port.is_open:
            serial_port.close()
        alarm_pin.close()

def main():
    # Initialize GPIO for alarm
    alarm_pin = OutputDevice(18, active_high=True, initial_value=False)

    # Setup serial port
    try:
        ser = serial.Serial(
            port='/dev/ttyUSB0',
            baudrate=9600,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1
        )
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    # Use the context manager to ensure resources are cleaned up
    with resource_manager(ser, alarm_pin):
        previous_alarm_state = False

        try:
            while True:
                try:
                    line = ser.readline().decode('ascii').strip()
                    if line and line.isdigit():
                        radiation_level = float(line)
                        print(f"Radiation level: {radiation_level:.2f} µSv/h")

                        # Determine alarm state
                        alarm_state = radiation_level > 50.0
                        if alarm_state != previous_alarm_state:
                            alarm_pin.value = alarm_state
                            previous_alarm_state = alarm_state
                            print("Alarm state changed:", "ON" if alarm_state else "OFF")

                except (ValueError, UnicodeDecodeError):
                    # Skip lines with non-ASCII or non-numeric data
                    continue
                except serial.SerialException as e:
                    print(f"I/O error: {e}")

                time.sleep(1)

        except KeyboardInterrupt:
            print("Program interrupted by user")

if __name__ == "__main__":
    main()

