from dataclasses import dataclass
from typing import Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPSReadings:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None

    def connect(self):
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info("Connected to GPS module.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port: {e}")
            self.serial_port = None

    def disconnect(self):
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                logging.info("Disconnected from GPS module.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

    def read_gpgga(self) -> Optional[GPSReadings]:
        try:
            line = self.serial_port.readline().decode('ascii', errors='ignore').strip()
            if line.startswith('$GPGGA'):
                fields = line.split(',')
                if len(fields) < 15 or fields[0][3:] != 'GGA':
                    logging.warning(f"Invalid GPGGA sentence: {line}")
                    return None

                try:
                    latitude = self._convert_to_decimal_degrees(fields[2], fields[3])
                    longitude = self._convert_to_decimal_degrees(fields[4], fields[5])
                    altitude = float(fields[9])
                    satellite_count = int(fields[7])
                    return GPSReadings(latitude, longitude, altitude, satellite_count)
                except (ValueError, IndexError) as e:
                    logging.error(f"Error parsing GPGGA sentence: {line} - {e}")
                    return None
            else:
                logging.debug(f"Ignored non-GPGGA sentence: {line}")
                return None
        except serial.SerialTimeoutException:
            logging.warning("Read timeout occurred.")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading from GPS: {e}")
            return None

    def _convert_to_decimal_degrees(self, value: str, direction: str) -> float:
        if not value or not direction:
            raise ValueError("Latitude or longitude value is missing.")
        degrees = int(value[:2])
        minutes = float(value[2:])
        decimal_degrees = degrees + minutes / 60.0
        if direction in ['S', 'W']:
            decimal_degrees = -decimal_degrees
        return decimal_degrees

def signal_handler(signal_received, frame):
    logging.info("Signal received, shutting down.")
    gps_reader.disconnect()
    sys.exit(0)

