import signal
import sys

class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.serial = None
        self._setup_signal_handlers()
        try:
            self.serial = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open port {port}: {e}")

    def _setup_signal_handlers(self):
        def signal_handler(sig, frame):
            self.close()
            sys.exit(0)
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def attach(self):
        try:
            self.serial.write(b"AT+CGNSPWR=1\r\n")
            time.sleep(1)
            if self.serial.in_waiting > 0:
                response = self.serial.read(self.serial.in_waiting).decode('utf-8')
                if "OK" in response:
                    return True
            return False
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to attach GPS: {e}")

    def detach(self):
        try:
            self.serial.write(b"AT+CGNSPWR=0\r\n")
            if self.serial.in_waiting > 0:
                response = self.serial.read(self.serial.in_waiting).decode('utf-8')
                if "OK" in response:
                    return True
            return False
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to detach GPS: {e}")

    def get_data(self):
        try:
            if self.serial.in_waiting > 0:
                line = self.serial.readline().decode('utf-8').strip()
                if line.startswith('$GPRMC') and len(line.split(',')) > 2:
                    parts = line.split(',')
                    if parts[2] == 'A':  # Status A means valid data
                        return parts
            return None
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to read data: {e}")

    def close(self):
        if self.serial and self.serial.is_open:
            try:
                self.serial.close()
            except serial.SerialException as e:
                raise RuntimeError(f"Failed to close port: {e}")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

# Example usage:
if __name__ == "__main__":
    try:
        with GPSController() as gps:
            if gps.attach():
