logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SimpleGPS:
    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None

    def connect(self):
        try:
            self.serial_connection = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info("Connected to GPS module.")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS module: {e}")
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.error("Serial connection is not open.")
            return None

        try:
            line = self.serial_connection.readline().decode('utf-8', errors='ignore').strip()
            if line:
                return line
            else:
                return None
        except Exception as e:
            logging.error(f"Error reading data: {e}")
            return None

    def parse_gga(self, line):
        try:
            if line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                parts = line.split(',')
                utc_time = parts[1]
                latitude = self._convert_to_decimal_degrees(parts[2], parts[3])
                longitude = self._convert_to_decimal_degrees(parts[4], parts[5])
                fix_quality = int(parts[6])
                num_satellites = int(parts[7])
                return {
                    'utc_time': utc_time,
                    'latitude': latitude,
                    'longitude': longitude,
                    'fix_quality': fix_quality,
                    'num_satellites': num_satellites
                }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
        return None

    def _convert_to_decimal_degrees(self, value, direction):
        if not value:
            return None
        degrees = float(value[:2])
        minutes = float(value[2:])
        decimal_degrees = degrees + minutes / 60.0
        if direction in ['S', 'W']:
            decimal_degrees = -decimal_degrees
        return decimal_degrees

    def close(self):
        try:
            if self.serial_connection and self.serial_connection.is_open:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
        except Exception as e:
            logging.error(f"Error closing serial connection: {e}")
        finally:
            self.serial_connection = None

if __name__ == '__main__':
    gps = SimpleGPS()

    if gps.connect():
        try:
            while True:
                line = gps.read_data()
                if line and line.startswith('$GPGGA') or line.startswith('$GNGGA'):
                    parsed_data = gps.parse_gga(line)
                    if parsed_data:
                        logging.info(f"Parsed GGA data: {parsed_data}")
                time.sleep(1)
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received, shutting down.")
        finally:
            gps.close()
