import json
import signal
import threading
from contextlib import contextmanager
from flask import Flask, request, jsonify, Response
from serial import Serial, SerialException, TimeoutError
from serial.tools.list_ports import comports

app = Flask(__name__)
app.config['DEBUG'] = False

# Thread-safe lock for UART access
uart_lock = threading.Lock()

# In-memory data store
data_store = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": True}]
data_store_lock = threading.Lock()

# Global variable to track the UART connection
uart_connection = None

# Context manager for UART connection
@contextmanager
def uart_connection_manager():
    global uart_connection
    try:
        with uart_lock:
            if uart_connection is None:
                uart_connection = Serial('/dev/ttyUSB0', baudrate=9600, bytesize=8, parity='N', stopbits=1, timeout=1)
            yield uart_connection
    except SerialException as e:
        raise RuntimeError("Failed to open UART port") from e
    finally:
        with uart_lock:
            if uart_connection is not None:
                uart_connection.close()
                uart_connection = None

# Signal handler to gracefully shutdown
def signal_handler(signum, frame):
    with uart_lock:
        if uart_connection is not None:
            uart_connection.close()
            uart_connection = None
    app.logger.info("Shutting down gracefully")
    exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

@app.route('/version', methods=['GET'])
def get_version():
    try:
        with uart_connection_manager() as uart:
            uart.write(b'*IDN?\n')
            uart.flush()
            response = uart.readline().decode('ascii').strip()
            if response:
                return Response(response, mimetype='text/plain')
            else:
                return Response("No response", status=504, mimetype='text/plain')
    except RuntimeError:
        return Response("Failed to open UART port", status=500, mimetype='text/plain')
    except TimeoutError:
        return Response("Timeout or no response", status=504, mimetype='text/plain')
    except Exception:
        return Response("Internal server error", status=502, mimetype='text/plain')

@app.route('/data', methods=['GET'])
def get_data():
    with data_store_lock:
        return jsonify(data_store)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    with data_store_lock:
        for item in data_store:
            if item['id'] == item_id:
                return jsonify(item)
        return Response("Item not found", status=404, mimetype='text/plain')

@app.route('/data', methods=['POST'])
def create_data_item():
    try:
        data = request.get_json()
        if not data or 'name' not in data or not data['name'] or 'done' not in data:
            return Response("Invalid input", status=400, mimetype='application/json')

        with data_store_lock:
            new_id = max(item['id'] for item in data_store) + 1
            new_item = {"id": new_id, "name": data['name'], "done": data['done']}
            data_store.append(new_item)

        return Response(json.dumps(new_item), status=201, mimetype='application/json')
    except Exception:
        return Response("Internal server error", status=502, mimetype='application/json')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

