from flask import Flask, request, jsonify, Response
import serial
import threading
import time
import json

app = Flask(__name__)

# In-memory list
data_list = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]

# Serial communication setup
serial_port = '/dev/ttyUSB0'
baud_rate = 9600
serial_config = {'baudrate': baud_rate, 'bytesize': serial.EIGHTBITS, 'parity': serial.PARITY_NONE, 'stopbits': serial.STOPBITS_ONE}

# Lock for thread-safe operations
lock = threading.Lock()

def read_serial_response(ser):
    time.sleep(0.1)
    response = ser.read_all().decode('utf-8')
    return response

def get_serial_response():
    try:
        with serial.Serial(serial_port, **serial_config) as ser:
            ser.write(b'*IDN?\n')
            response = read_serial_response(ser)
            return response
    except Exception as e:
        return f"503 Service Unavailable: {str(e)}"

@app.route('/version', methods=['GET'])
def version():
    response = get_serial_response()
    if response.startswith("503"):
        return Response(response, status=503, mimetype='text/html')
    else:
        return Response(response.replace('\n', '<br>'), mimetype='text/html')

@app.route('/getdata', methods=['GET'])
def get_data():
    with lock:
        return jsonify(data_list)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    with lock:
        for item in data_list:
            if item['id'] == item_id:
                return jsonify(item)
        return Response("404 Not Found", status=404)

