def get_post(item_id, name):
    with lock:
        new_item = {"id": item_id, "name": name, "done": False}
        data_list.append(new_item)
        return jsonify(data_list)

@app.route('/postjson', methods=['POST'])
def post_json():
    try:
        if request.content_type == 'application/json':
            new_item = request.get_json()
        else:
            new_item = request.form.to_dict()

        new_item['id'] = max(item['id'] for item in data_list) + 1 if data_list else 1
        new_item['name'] = new_item.get('name', '')
        new_item['done'] = str(new_item.get('done', '')).lower() in ['true', '1']

        with lock:
            data_list.append(new_item)
        return jsonify(data_list), 201
    except Exception as e:
        return Response(f"400 Bad Request: {str(e)}", status=400)

@app.route('/postjson', methods=['GET'])
def get_post_json():
    with lock:
        return jsonify(data_list)

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000)
    except Exception as e:
        print(f"Error: {str(e)}")
    finally:
        # Ensure serial port is closed
        try:
            ser = serial.Serial(serial_port, **serial_config)
            ser.close()
        except Exception as e:
            print(f"Error closing serial port: {str(e)}")

