import serial
import time
import sys

def main():
    try:
        # Open the serial connection
        with serial.Serial('/dev/rfcomm4', 38400, timeout=1) as ser:
            while True:
                try:
                    # Prompt the user for a command
                    command = input("Enter command (type 'exit' to quit): ")

                    # Check for exit command
                    if command.lower() == 'exit':
                        print("Exiting program.")
                        break

                    # Format the command
                    formatted_command = f"X{command}\n"

                    # Send the command over the serial connection
                    ser.write(formatted_command.encode())

                    # Delay after transmission
                    time.sleep(0.1)

                except serial.SerialException as e:
                    raise RuntimeError(f"Serial connection error: {e}")

    except serial.SerialException as e:
        raise RuntimeError(f"Failed to open serial connection: {e}")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting gracefully.")

    finally:
        # Ensure the serial connection is closed
        if 'ser' in locals() and ser.is_open:
            ser.close()
            print("Serial connection closed.")

if __name__ == "__main__":
    try:
        main()
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

